
import argparse
import csv
import statistics
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


METRICS = {
    "revision_count": "Churn (revision count)",
    "days_since_last_edit": "Age (days since last edit)",
}


def load_results(path):
    """Read the history metrics generated by history_metrics.py."""
    with open(path, newline="", encoding="utf-8") as file:
        reader = csv.DictReader(file)
        required = {"file", *METRICS.keys()}

        if not required.issubset(reader.fieldnames or []):
            raise ValueError(f"Missing required columns in {path}")

        rows = []
        for row in reader:
            rows.append({
                "file": row["file"],
                "revision_count": int(row["revision_count"]),
                "days_since_last_edit": float(
                    row["days_since_last_edit"]
                ),
            })

    if not rows:
        raise ValueError(f"No data found in {path}")

    return rows


def summarize(rows, dataset):
    """Calculate descriptive statistics for each metric."""
    results = []

    for metric in METRICS:
        values = [row[metric] for row in rows]

        results.append({
            "dataset": dataset,
            "metric": metric,
            "count": len(values),
            "mean": round(statistics.mean(values), 3),
            "median": round(statistics.median(values), 3),
            "std_dev": round(
                statistics.pstdev(values), 3
            ),
            "minimum": min(values),
            "maximum": max(values),
        })

    return results


def save_summary(rows, output):
    fieldnames = [
        "dataset", "metric", "count", "mean",
        "median", "std_dev", "minimum", "maximum"
    ]

    with open(output, "w", newline="", encoding="utf-8") as file:
        writer = csv.DictWriter(file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def create_graph(skills, source, metric, output):
    """Create side-by-side distribution plots."""
    skills_values = [row[metric] for row in skills]
    source_values = [row[metric] for row in source]

    fig, axes = plt.subplots(1, 2, figsize=(12, 5))

    for ax, values, label in zip(
        axes,
        [skills_values, source_values],
        ["Agent Skills", "Source Code"]
    ):
        ax.hist(values, bins=20, edgecolor="black")
        ax.set_title(label)
        ax.set_xlabel(METRICS[metric])
        ax.set_ylabel("Number of files")

    fig.suptitle(
        f"Agent Skills vs Source Code: {METRICS[metric]}"
    )
    fig.tight_layout()
    fig.savefig(output, dpi=200)
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser(
        description="Compare churn and age distributions."
    )
    parser.add_argument("--skills", required=True)
    parser.add_argument("--source", required=True)
    parser.add_argument("--output-dir", default="results")

    args = parser.parse_args()

    skills = load_results(args.skills)
    source = load_results(args.source)

    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    summary = (
        summarize(skills, "Agent Skills")
        + summarize(source, "Source Code")
    )

    save_summary(
        summary, output_dir / "history_summary.csv"
    )

    for metric in METRICS:
        create_graph(
            skills,
            source,
            metric,
            output_dir / f"{metric}_comparison.png"
        )

    print(f"Analyzed {len(skills)} agent skills.")
    print(f"Analyzed {len(source)} source files.")
    print(f"Results saved to {output_dir}")


if __name__ == "__main__":
    main()
